import path from 'path';
import {posixPath, Globby, parseURLPath} from '@docusaurus/utils';

// Globby that fix Windows path patterns
// See https://github.com/facebook/docusaurus/pull/4222#issuecomment-795517329
export async function safeGlobby(
  patterns: string[],
  options?: Globby.GlobbyOptions,
): Promise<string[]> {
  // Required for Windows support, as paths using \ should not be used by globby
  // (also using the windows hard drive prefix like c: is not a good idea)
  const globPaths = patterns.map((dirPath) =>
    posixPath(path.relative(process.cwd(), dirPath)),
  );

  return Globby(globPaths, options);
}

export class ResolvedLinkPath {
  pathname: string;
  search?: string;
  hash?: string;
  sourcePath: string;
  rawLink: string;

  constructor(fields: {
    pathname: string;
    search?: string;
    hash?: string;
    sourcePath: string;
    rawLink: string;
  }) {
    this.pathname = fields.pathname;
    this.search = fields.search;
    this.hash = fields.hash;
    this.sourcePath = fields.sourcePath;
    this.rawLink = fields.rawLink;
  }

  static fromRawLink(rawLink: string, sourcePath: string): ResolvedLinkPath {
    const parsed = parseURLPath(rawLink, sourcePath);
    return new ResolvedLinkPath({
      pathname: parsed.pathname,
      search: parsed.search,
      hash: parsed.hash,
      sourcePath,
      rawLink,
    });
  }
}

