// Docusaurus pages can be collected under a pathname with or without a
// trailing slash (depending on the site trailingSlash configuration)
// Links may use any of the 2 pathname variants, and both should work
// See https://github.com/facebook/docusaurus/issues/10130
static getPossiblePathnames(pathname: string): string[] {
  const decodedPathname = decodeURI(pathname);
  return _.uniq([
    pathname,
    decodedPathname,
    addTrailingSlash(pathname),
    removeTrailingSlash(pathname),
    addTrailingSlash(decodedPathname),
    removeTrailingSlash(decodedPathname),
  ]);
}

isAnchorBrokenLink(linkPath: ResolvedLinkPath) {
  const collectedLinks = this.collectedLinks;
  const validPathnames = this.validPathnames;
  const {pathname, hash, search, sourcePath, rawLink} = linkPath;
  const normalizedPathname = addLeadingSlash(pathname);
  const reconstructed = `${normalizedPathname}${
    search === undefined ? '' : `?${search}`
  }${hash === undefined ? '' : `#${hash}`}`;
  const collectedKey = reconstructed.split(/[?#]/)[0]!;
  const rawPath = rawLink.split('#')[0]!.split('?')[0]!;
  const lookupPath =
    rawPath === pathname || rawPath === decodeURI(pathname)
      ? rawPath
      : pathname;
  const possiblePathnames = BrokenLinksHelper.getPossiblePathnames(pathname);
  const resolvedSelf =
    sourcePath === pathname ||
    sourcePath === decodeURI(pathname) ||
    addLeadingSlash(sourcePath) === normalizedPathname;

  // Link has no hash: it can't be a broken anchor link
  if (hash === undefined) {
    return false;
  }
  // Link has empty hash ("#", "/page#"...): we do not report it as broken
  // Empty hashes are used for various weird reasons, by us and other users...
  // See for example: https://github.com/facebook/docusaurus/pull/6003
  if (hash === '') {
    return false;
  }
  const targetPage = possiblePathnames
    .map((p) => collectedLinks.get(p))
    .find((page) => page !== undefined);
  // link with anchor to a page that does not exist (or did not collect any
  // link/anchor) is considered as a broken anchor
  if (!targetPage) {
    return true;
  }
  const anchorId = hash.startsWith('#') ? hash.slice(1) : hash;
  const knownPage =
    [collectedKey, lookupPath, ...possiblePathnames].some((p) =>
      validPathnames.has(p),
    ) || (resolvedSelf && validPathnames.has(sourcePath));

